    private fun builder(name: String) = ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)

    private fun filled(path: String): ImageVector = builder("spp").addPath(addPathNodes(path), fill = SolidColor(Color.Black)).build()

    private fun stroked(path: String): ImageVector =
        builder("spp").addPath(addPathNodes(path), fill = null, stroke = SolidColor(Color.Black), strokeLineWidth = 2f, strokeLineJoin = StrokeJoin.Round).build()
